INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (1, 0, 72, 11, 0, "でも、諦めるわけにはいかないなって。\n時々森に通って、300年を３年くらい\nに、縮めようと思ってるんです！", 0, 10, 72037, 1, 1);
